class LoanTest(unittest.TestCase):
    def test_lending_an_available_tool_records_a_loan_due_in_14_days(self):
        loan = self.library.lend("T-7", "C-102", on=date(2026, 3, 1))
        self.assertEqual(loan.due_date, date(2026, 3, 15))

    def test_returned_tool_is_available_again(self):
        self.library.lend("T-7", "C-102", on=date(2026, 3, 1))
        self.library.receive_return("T-7")
        self.assertTrue(self.library.is_available("T-7"))
